diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..71399c7 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,49 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS_BASE = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006-T1: descuento global del 10 % sobre el total de líneas", () => {
+  assert.deepEqual(calcularFactura(LINEAS_BASE, { descuentoGlobal: 10 }), { totalCentavos: 9945, ivaCentavos: 1293, netoCentavos: 8652 });
+});
+
+test("RF-006-T2: sin descuento el resultado no cambia", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_BASE), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_BASE, {}), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_BASE, { descuentoGlobal: 0 }), esperado);
+});
+
+test("RF-006-T3: 100 % deja el total en cero", () => {
+  assert.deepEqual(calcularFactura(LINEAS_BASE, { descuentoGlobal: 100 }), { totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0 });
+});
+
+test("RF-006-T4: un solo Math.round sobre el total ya descontado", () => {
+  // 1005 × 50 % = 502,5 → 503 (si se redondeara el descuento y se restara, daría 502)
+  assert.deepEqual(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1005 }], { descuentoGlobal: 50 }), { totalCentavos: 503, ivaCentavos: 65, netoCentavos: 438 });
+});
+
+test("RF-006-T5: descuento fuera de 0–100 se rechaza", () => {
+  assert.throws(() => calcularFactura(LINEAS_BASE, { descuentoGlobal: -1 }), RangeError);
+  assert.throws(() => calcularFactura(LINEAS_BASE, { descuentoGlobal: 101 }), RangeError);
+});
+
+test("RF-006-T6: descuento no entero se rechaza (ADR-001)", () => {
+  assert.throws(() => calcularFactura(LINEAS_BASE, { descuentoGlobal: 10.5 }), RangeError);
+  assert.throws(() => calcularFactura(LINEAS_BASE, { descuentoGlobal: "10" }), RangeError);
+  assert.throws(() => calcularFactura(LINEAS_BASE, { descuentoGlobal: NaN }), RangeError);
+});
+
+test("RF-006-T7: emitirFactura no cambia (sigue congelada y sin descuento)", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS_BASE });
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.totalCentavos, 11050);
+  assert.equal(f.estado, "emitida");
+});
